static dan_str dm_Dsb_str(const dm_Dsb *d) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "{");
    bool first = true;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        if (!first) dan_buf_add(&b, ", ");
        first = false;
        dan_buf_add(&b, dan_quote_str(d->keys[e]));
        dan_buf_add(&b, ": ");
        dan_buf_add(&b, dan_bool_to_str(d->vals[e]));
    }
    dan_buf_add(&b, "}");
    return dan_buf_str(&b);
}
static void dm_Dsb_write(const dm_Dsb *d) { fputs(dm_Dsb_str(d), stdout); }


static bool dm_Dsb_eq(const dm_Dsb *x, const dm_Dsb *y) {
    if (x->len != y->len) return false;
    for (int64_t e = 0; e < x->n; e++) {
        if (!x->alive[e]) continue;
        int64_t f = dm_Dsb_lookup(y, x->keys[e], x->hashes[e]);
        if (f < 0) return false;
        bool a = x->vals[e]; bool b = y->vals[f];
        if (!((a == b))) return false;
    }
    return true;
}


/* ---- dictionary {стр: [встроенные.Вариант]} ---- */
struct dm_DsLTvstroennyeu2eVariant { dan_hdr h; int64_t len, n, cap, slots; dan_str *keys; dl_LTvstroennyeu2eVariant* *vals; uint64_t *hashes; bool *alive; int64_t *index; };

static void dm_DsLTvstroennyeu2eVariant_destroy(dan_hdr *h) {
    dm_DsLTvstroennyeu2eVariant *d = (dm_DsLTvstroennyeu2eVariant *)(void *)h;
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) { dan_str_release(d->keys[e]); dl_LTvstroennyeu2eVariant_release(d->vals[e]); }
    dan_free(d->hashes);
    dan_free(d);
}
static dm_DsLTvstroennyeu2eVariant *dm_DsLTvstroennyeu2eVariant_new(void) {
    dm_DsLTvstroennyeu2eVariant *d = dan_alloc(sizeof *d);
    dan_hdr_new(&d->h, dm_DsLTvstroennyeu2eVariant_destroy);
    d->len = d->n = d->cap = d->slots = 0;
    d->keys = NULL; d->vals = NULL; d->hashes = NULL; d->alive = NULL; d->index = NULL;
    return d;
}
static dm_DsLTvstroennyeu2eVariant *dm_DsLTvstroennyeu2eVariant_new_detached(void) {
    dm_DsLTvstroennyeu2eVariant *d = dan_alloc(sizeof *d);
    dan_hdr_detached(&d->h);
    d->len = d->n = d->cap = d->slots = 0;
    d->keys = NULL; d->vals = NULL; d->hashes = NULL; d->alive = NULL; d->index = NULL;
    return d;
}
static dm_DsLTvstroennyeu2eVariant *dm_DsLTvstroennyeu2eVariant_share(dm_DsLTvstroennyeu2eVariant *d) { if (d) dan_hdr_share(&d->h); return d; }
static void dm_DsLTvstroennyeu2eVariant_release(dm_DsLTvstroennyeu2eVariant *d) { if (d) dan_hdr_release(&d->h, dm_DsLTvstroennyeu2eVariant_destroy); }
static void dm_DsLTvstroennyeu2eVariant_give(dm_DsLTvstroennyeu2eVariant *d) { if (d) dan_hdr_give(&d->h, dm_DsLTvstroennyeu2eVariant_destroy); }

/* все части словаря - в одном блоке памяти (одно выделение вместо пяти): отпечатки,
   таблица поиска, ключи, значения и признаки «запись есть» на cap записей */
static void dm_DsLTvstroennyeu2eVariant_block(dm_DsLTvstroennyeu2eVariant *d, int64_t cap) {
    int64_t s = 8;
    while (s < 2 * cap) s *= 2;
    size_t c = (size_t)cap, kb = (sizeof(dan_str) * c + 7) & ~(size_t)7, vb = (sizeof(dl_LTvstroennyeu2eVariant*) * c + 7) & ~(size_t)7;
    char *b = dan_alloc(8 * c + 8 * (size_t)s + kb + vb + c);
    d->hashes = (uint64_t *)(void *)b;
    d->index = (int64_t *)(void *)(b + 8 * c);
    d->keys = (dan_str *)(void *)(b + 8 * c + 8 * (size_t)s);
    d->vals = (dl_LTvstroennyeu2eVariant* *)(void *)(b + 8 * c + 8 * (size_t)s + kb);
    d->alive = (bool *)(void *)(b + 8 * c + 8 * (size_t)s + kb + vb);
    d->cap = cap;
    d->slots = s;
}
static void dm_DsLTvstroennyeu2eVariant_reindex(dm_DsLTvstroennyeu2eVariant *d) {
    int64_t s = d->slots;
    for (int64_t i = 0; i < s; i++) d->index[i] = -1;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        int64_t p = (int64_t)(d->hashes[e] & (uint64_t)(s - 1));
        while (d->index[p] >= 0) p = (p + 1) & (s - 1);
        d->index[p] = e;
    }
}
static int64_t dm_DsLTvstroennyeu2eVariant_lookup(const dm_DsLTvstroennyeu2eVariant *d, dan_str k, uint64_t h) {
    if (!d->slots) return -1;
    for (int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));; p = (p + 1) & (d->slots - 1)) {
        int64_t e = d->index[p];
        if (e < 0) return -1;
        if (d->alive[e] && d->hashes[e] == h) { dan_str a = d->keys[e], b = k; if (dan_str_eq(a, b)) return e; }
    }
}
static void dm_DsLTvstroennyeu2eVariant_grow(dm_DsLTvstroennyeu2eVariant *d) {   /* убирает удалённые записи и увеличивает таблицу */
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dan_str *keys = d->keys; dl_LTvstroennyeu2eVariant* *vals = d->vals; uint64_t *hashes = d->hashes; bool *alive = d->alive;
    int64_t n = d->n;
    dm_DsLTvstroennyeu2eVariant_block(d, cap);
    for (int64_t e = 0; e < n; e++) {
        if (!alive[e]) continue;
        d->keys[m] = keys[e]; d->vals[m] = vals[e]; d->hashes[m] = hashes[e]; d->alive[m] = true; m++;
    }
    dan_free(hashes);
    d->n = m;
    dm_DsLTvstroennyeu2eVariant_reindex(d);
}
static void dm_DsLTvstroennyeu2eVariant_put(dm_DsLTvstroennyeu2eVariant *d, dan_str k, dl_LTvstroennyeu2eVariant* v) {
    uint64_t h = dan_hash_s(k);
    int64_t e = dm_DsLTvstroennyeu2eVariant_lookup(d, k, h);
    if (e >= 0) { dl_LTvstroennyeu2eVariant* old = d->vals[e]; d->vals[e] = dl_LTvstroennyeu2eVariant_share(v); dl_LTvstroennyeu2eVariant_release(old); (void)old; return; }
    if (d->n == d->cap) dm_DsLTvstroennyeu2eVariant_grow(d);
    e = d->n++;
    d->keys[e] = dan_str_share(k); d->vals[e] = dl_LTvstroennyeu2eVariant_share(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
    d->index[p] = e;
}
/* запись в новый словарь значений, которые уже учтены (копия для задачи) */
static void dm_DsLTvstroennyeu2eVariant_put_raw(dm_DsLTvstroennyeu2eVariant *d, dan_str k, dl_LTvstroennyeu2eVariant* v) {
    uint64_t h = dan_hash_s(k);
    if (d->n == d->cap) dm_DsLTvstroennyeu2eVariant_grow(d);
    int64_t e = d->n++;
    d->keys[e] = k; d->vals[e] = v; d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
    d->index[p] = e;
}
/* место значения по ключу; если ключа нет, запись создаётся со значением v (одно обращение
   вместо получить и записать) */
static dl_LTvstroennyeu2eVariant* *dm_DsLTvstroennyeu2eVariant_slot(dm_DsLTvstroennyeu2eVariant *d, dan_str k, dl_LTvstroennyeu2eVariant* v) {
    uint64_t h = dan_hash_s(k);
    int64_t e = dm_DsLTvstroennyeu2eVariant_lookup(d, k, h);
    if (e < 0) {
        if (d->n == d->cap) dm_DsLTvstroennyeu2eVariant_grow(d);
        e = d->n++;
        d->keys[e] = dan_str_share(k); d->vals[e] = dl_LTvstroennyeu2eVariant_share(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
        int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
        while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
        d->index[p] = e;
    }
    return &d->vals[e];
}
static dm_DsLTvstroennyeu2eVariant *dm_DsLTvstroennyeu2eVariant_from(int64_t n, const dan_str *ks, const dl_LTvstroennyeu2eVariant* *vs) {
    dm_DsLTvstroennyeu2eVariant *d = dm_DsLTvstroennyeu2eVariant_new();
    for (int64_t i = 0; i < n; i++) dm_DsLTvstroennyeu2eVariant_put(d, ks[i], vs[i]);
    return d;
}
static dl_LTvstroennyeu2eVariant* dm_DsLTvstroennyeu2eVariant_get(const dm_DsLTvstroennyeu2eVariant *d, dan_str k, int line) {
    int64_t e = dm_DsLTvstroennyeu2eVariant_lookup(d, k, dan_hash_s(k));
    if (e < 0) dan_key_error(dan_quote_str(k), line);
    return d->vals[e];
}
static dl_LTvstroennyeu2eVariant* *dm_DsLTvstroennyeu2eVariant_at(dm_DsLTvstroennyeu2eVariant *d, dan_str k, int line) {
    int64_t e = dm_DsLTvstroennyeu2eVariant_lookup(d, k, dan_hash_s(k));
    if (e < 0) dan_key_error(dan_quote_str(k), line);
    return &d->vals[e];
}
static bool dm_DsLTvstroennyeu2eVariant_contains(const dm_DsLTvstroennyeu2eVariant *d, dan_str k) { return dm_DsLTvstroennyeu2eVariant_lookup(d, k, dan_hash_s(k)) >= 0; }

static do_LTvstroennyeu2eVariant dm_DsLTvstroennyeu2eVariant_find(const dm_DsLTvstroennyeu2eVariant *d, dan_str k) {
    int64_t e = dm_DsLTvstroennyeu2eVariant_lookup(d, k, dan_hash_s(k));
    return e < 0 ? do_LTvstroennyeu2eVariant_none() : do_LTvstroennyeu2eVariant_some(d->vals[e]);
}
static dl_LTvstroennyeu2eVariant* dm_DsLTvstroennyeu2eVariant_get_or(const dm_DsLTvstroennyeu2eVariant *d, dan_str k, dl_LTvstroennyeu2eVariant* v) {
    int64_t e = dm_DsLTvstroennyeu2eVariant_lookup(d, k, dan_hash_s(k));
    return e < 0 ? v : d->vals[e];
}
static void dm_DsLTvstroennyeu2eVariant_remove(dm_DsLTvstroennyeu2eVariant *d, dan_str k) {
    int64_t e = dm_DsLTvstroennyeu2eVariant_lookup(d, k, dan_hash_s(k));
    if (e >= 0) { d->alive[e] = false; d->len--; dan_str_release(d->keys[e]); dl_LTvstroennyeu2eVariant_release(d->vals[e]); }
}
static dl_Ls *dm_DsLTvstroennyeu2eVariant_keys(const dm_DsLTvstroennyeu2eVariant *d) {
    dl_Ls *r = dl_Ls_from(0, NULL);
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) dl_Ls_push(r, d->keys[e]);
    return r;
}
static dl_LLTvstroennyeu2eVariant *dm_DsLTvstroennyeu2eVariant_values(const dm_DsLTvstroennyeu2eVariant *d) {
    dl_LLTvstroennyeu2eVariant *r = dl_LLTvstroennyeu2eVariant_from(0, NULL);
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) dl_LLTvstroennyeu2eVariant_push(r, d->vals[e]);
    return r;
}
/* копия для изменения: записи переносятся вместе с готовыми отпечатками (без повторного
   вычисления), место - с запасом вдвое, чтобы следующая запись не перестраивала таблицу */
static dm_DsLTvstroennyeu2eVariant *dm_DsLTvstroennyeu2eVariant_copy(const dm_DsLTvstroennyeu2eVariant *d) {
    dm_DsLTvstroennyeu2eVariant *r = dm_DsLTvstroennyeu2eVariant_new();
    if (d->len == 0) return r;
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dm_DsLTvstroennyeu2eVariant_block(r, cap);
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        r->keys[m] = dan_str_share(d->keys[e]); r->vals[m] = dl_LTvstroennyeu2eVariant_share(d->vals[e]); r->hashes[m] = d->hashes[e]; r->alive[m] = true; m++;
    }
    r->n = r->len = m;
    dm_DsLTvstroennyeu2eVariant_reindex(r);
    return r;
}
static dm_DsLTvstroennyeu2eVariant *dm_DsLTvstroennyeu2eVariant_mut(dm_DsLTvstroennyeu2eVariant **pp) {
    dm_DsLTvstroennyeu2eVariant *d = *pp;
    if (d->h.rc > 1) { dm_DsLTvstroennyeu2eVariant *r = dm_DsLTvstroennyeu2eVariant_copy(d); r->h.rc = 1; d->h.rc--; *pp = r; return r; }
    return d;
}
static dan_str dm_DsLTvstroennyeu2eVariant_str(const dm_DsLTvstroennyeu2eVariant *d) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "{");
    bool first = true;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        if (!first) dan_buf_add(&b, ", ");
        first = false;
        dan_buf_add(&b, dan_quote_str(d->keys[e]));
        dan_buf_add(&b, ": ");
        dan_buf_add(&b, dl_LTvstroennyeu2eVariant_str(d->vals[e]));
    }
    dan_buf_add(&b, "}");
    return dan_buf_str(&b);
}
static void dm_DsLTvstroennyeu2eVariant_write(const dm_DsLTvstroennyeu2eVariant *d) { fputs(dm_DsLTvstroennyeu2eVariant_str(d), stdout); }


static bool dm_DsLTvstroennyeu2eVariant_eq(const dm_DsLTvstroennyeu2eVariant *x, const dm_DsLTvstroennyeu2eVariant *y) {
    if (x->len != y->len) return false;
    for (int64_t e = 0; e < x->n; e++) {
        if (!x->alive[e]) continue;
        int64_t f = dm_DsLTvstroennyeu2eVariant_lookup(y, x->keys[e], x->hashes[e]);
        if (f < 0) return false;
        dl_LTvstroennyeu2eVariant* a = x->vals[e]; dl_LTvstroennyeu2eVariant* b = y->vals[f];
        if (!(dl_LTvstroennyeu2eVariant_eq(a, b))) return false;
    }
    return true;
}


